package com.pp.shaderlod.lod.terrain;
import com.pp.shaderlod.*;import com.pp.shaderlod.optimization.*;import net.minecraft.client.Minecraft;import net.minecraft.world.entity.Entity;import net.irisshaders.iris.Iris;import net.irisshaders.iris.api.v0.IrisApi;import net.irisshaders.iris.pipeline.IrisRenderingPipeline;
/** Existing fixed radius/explicit replacement-coverage policy, normal loader tick and Options consumer. */
public final class GeometryLodController {
 private record State(GeometryCoverageGuard.Scene scene,GeometryLodPolicy.Decision decision,long flags,long lifecycle){}
 private static final GeometryCoverageGuard coverage=new GeometryCoverageGuard();private static GeometryCoverageGuard.Scene observed;
 private static volatile State state=new State(null,new GeometryLodPolicy.Decision(false,16,"not ready"),-1,-1);
 private static int stable,cap=16;private static boolean acknowledged;
 private GeometryLodController(){}
 private static long observedFlags=-1,observedLifecycle=-1;
 /** A generation transition latches coverage loss even if Off→On/Apply occurs between ticks. */
 private static void checkGenerations(){long flags=OptimizationConfig.generation(),life=com.pp.shaderlod.integration.makeupquad.MakeUpQuadLifecycle.epoch();if(observedFlags<0||flags!=observedFlags||life!=observedLifecycle){coverage.invalidate();stable=0;observed=null;acknowledged=false;state=new State(null,new GeometryLodPolicy.Decision(false,cap,"terrain inputs changed; reconfirm coverage"),flags,life);}observedFlags=flags;observedLifecycle=life;}

 private static boolean active(){var c=OptimizationRuntimeContext.core();return com.pp.shaderlod.fabric.FabricLodConfig.loaded()&&c!=null&&c.settings().enabled()&&c.preset()==LodPreset.PERFORMANCE&&OptimizationConfig.requested(OptimizationId.TERRAIN_RADIUS)&&!com.pp.shaderlod.integration.makeupquad.MakeUpQuadLifecycle.suspended();}
 public static void tick(){checkGenerations();var client=Minecraft.getInstance();Object world=client.level;Entity camera=client.getCameraEntity();int requested=client.options.renderDistance().get();Object pipeline=null;boolean irisReady=false;DhTerrainInputs.Readiness dh=new DhTerrainInputs.Readiness(false,0);boolean selected=active();
  if(selected&&world!=null&&net.fabricmc.loader.api.FabricLoader.getInstance().isModLoaded("distanthorizons")){try{pipeline=Iris.getPipelineManager().getPipelineNullable();irisReady=IrisApi.getInstance().isShaderPackInUse()&&pipeline instanceof IrisRenderingPipeline p&&p.getDHTerrainShader().isPresent()&&p.getDHCompat()!=null&&p.getDHCompat().getInstance()!=null;if(irisReady)dh=DhTerrainInputs.read(requested);}catch(RuntimeException|LinkageError unsupported){irisReady=false;}}
  var scene=selected&&world!=null&&camera!=null&&irisReady&&dh.ready()?new GeometryCoverageGuard.Scene(world,pipeline,camera,GeometryCoverageGuard.cell(camera.getX()),GeometryCoverageGuard.cell(camera.getY()),GeometryCoverageGuard.cell(camera.getZ()),requested,cap,dh.chunks()):null;
  if(scene==null||!scene.matches(observed)){stable=0;observed=scene;}else if(stable<Integer.MAX_VALUE)stable++;
  boolean confirmed=coverage.confirmed(stable>=600?scene:null,acknowledged);var decision=GeometryLodPolicy.decide(new GeometryLodPolicy.Inputs(selected,selected,world!=null,irisReady,dh.ready(),confirmed,stable,600,cap));state=new State(scene,decision,observedFlags,observedLifecycle);
 }
 public static int effectiveChunks(int original){checkGenerations();var current=state;if(!active()||current.flags()!=OptimizationConfig.generation()||current.lifecycle()!=com.pp.shaderlod.integration.makeupquad.MakeUpQuadLifecycle.epoch()||!current.decision().active()||!coverage.isConfirmed(current.scene()))return original;var client=Minecraft.getInstance();Entity camera=client.getCameraEntity();var scene=current.scene();if(scene==null||camera==null||scene.cap()!=cap||scene.requestedChunks()!=client.options.renderDistance().get()||scene.pipeline()!=Iris.getPipelineManager().getPipelineNullable()||!scene.contains(client.level,camera,camera.getX(),camera.getY(),camera.getZ())){coverage.invalidate();return original;}return current.decision().apply(original);}
 public static boolean confirmCurrentScene(){checkGenerations();var client=Minecraft.getInstance();var camera=client.getCameraEntity();var scene=state.scene();if(client.level==null||client.player==null||camera==null||scene==null||!scene.contains(client.level,camera,camera.getX(),camera.getY(),camera.getZ())||scene.pipeline()!=Iris.getPipelineManager().getPipelineNullable()||scene.requestedChunks()!=client.options.renderDistance().get()||scene.cap()!=cap||!active()||stable<600)return false;coverage.rearm();acknowledged=true;if(stable>=600)coverage.confirmed(scene,true);return true;}
 public static String confirmationReason(){return state.scene()==null?"The current DH scene is not eligible for terrain replacement.":stable<600?"Warm this DH scene for "+((600-stable+19)/20)+" more seconds, then inspect coverage and confirm.":"Inspect complete DH replacement coverage before confirming this current scene.";}
 public static void revokeCurrentScene(){acknowledged=false;coverage.invalidate();var current=state;state=new State(current.scene(),new GeometryLodPolicy.Decision(false,cap,"DH replacement coverage revoked"),-1,-1);}
 public static void setCap(int value){cap=Math.clamp(value,8,32);revokeCurrentScene();}public static int cap(){return cap;}public static int stableTicks(){return stable;}
}
